static void report(const char* name,
                   const std::vector<int>& comp,
                   const std::vector<int>& arrival,
                   const std::vector<int>& burst)
{
    const std::size_t n{ comp.size() };

    std::cout << name << " completion";
    for (std::size_t i = 0; i < n; ++i) std::cout << ' ' << comp[i];
    std::cout << "\n";

    std::cout << name << " turnaround";
    for (std::size_t i = 0; i < n; ++i) std::cout << ' ' << (comp[i] - arrival[i]);
